/*!
 * PWA devre disi. Bu dosya, daha once kaydedilmis service worker'lari
 * temizleyen bir "kill-switch"tir: eski worker cache-first calistigi icin
 * aksi halde ziyaretcilere bayat (cache'lenmis) sayfalar servis edilir.
 *
 * Kurulumda beklemeden etkinlesir, etkinlesince tum cache'leri siler,
 * kendini kaydini siler ve acik sekmeleri yeniler.
 */
self.addEventListener('install', function () {
  self.skipWaiting();
});

self.addEventListener('activate', function (event) {
  event.waitUntil(
    Promise.all([
      caches.keys().then(function (keys) {
        return Promise.all(keys.map(function (key) {
          return caches.delete(key);
        }));
      }),
      self.registration.unregister()
    ]).then(function () {
      return self.clients.matchAll({ type: 'window' });
    }).then(function (clients) {
      clients.forEach(function (client) {
        try {
          client.navigate(client.url);
        } catch (err) {
          /* yoksay */
        }
      });
    })
  );
});